with open('source.kt', 'r') as f:
    lines = f.readlines()

issues = []
for i, line in enumerate(lines, 1):
    stripped = line.rstrip('\n')
    if stripped.strip() == '':
        continue
    # Check for lines with 4+ consecutive spaces followed by more spaces (comment residue)
    if '                        ' in stripped and not stripped.strip().startswith('//'):
        # Check if the leading spaces are more than 2x the indentation level of previous line
        leading = len(stripped) - len(stripped.lstrip())
        prev_leading = 0
        if i > 1:
            prev = lines[i-2].rstrip('\n')
            if prev.strip():
                prev_leading = len(prev) - len(prev.lstrip())
        if leading > prev_leading + 8 and leading > 20:
            issues.append(f'Line {i}: {leading} leading spaces (prev: {prev_leading})')

for iss in issues:
    print(iss)
if not issues:
    print('No indentation issues found')
"

