class MainActivity : ComponentActivity() {
    private val volumeKeyEventFlow = MutableSharedFlow<Int>(extraBufferCapacity = 1)

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        window.addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)
        enableEdgeToEdge()
        setContent {
            LatentTheme {
                MainScreen(volumeKeyEventFlow)
            }
        }
    }

    override fun onKeyDown(keyCode: Int, event: KeyEvent?): Boolean {
        if (keyCode == KeyEvent.KEYCODE_VOLUME_UP || keyCode == KeyEvent.KEYCODE_VOLUME_DOWN) {
            volumeKeyEventFlow.tryEmit(keyCode)
            return true
        }
        return super.onKeyDown(keyCode, event)
    }

    fun getRecordingReceiver(): android.content.BroadcastReceiver = recordingReceiver

    private val recordingReceiver = object : android.content.BroadcastReceiver() {
        override fun onReceive(context: android.content.Context?, intent: android.content.Intent?) {
            if (intent?.action == PACKAGE_ACTION_TOGGLE_VIDEO) {
                volumeKeyEventFlow.tryEmit(KeyEvent.KEYCODE_VOLUME_DOWN)
            }
        }
    }
}

const val PACKAGE_ACTION_TOGGLE_VIDEO = "com.pixelary.latent.TOGGLE_VIDEO"
const val PERMISSION_CAMERA = Manifest.permission.CAMERA
const val PERMISSION_AUDIO = Manifest.permission.RECORD_AUDIO
const val PERMISSION_FINE_LOCATION = Manifest.permission.ACCESS_FINE_LOCATION
const val PERMISSION_COARSE_LOCATION = Manifest.permission.ACCESS_COARSE_LOCATION

val REQUIRED_PERMISSIONS = arrayOf(
    PERMISSION_CAMERA, PERMISSION_AUDIO, PERMISSION_FINE_LOCATION, PERMISSION_COARSE_LOCATION
)

val REQUIRED_PERMISSIONS_FOR_CHECK = arrayOf(
    PERMISSION_CAMERA, PERMISSION_AUDIO, PERMISSION_FINE_LOCATION
)

private fun Context.hasAllPermissions(): Boolean {
    return REQUIRED_PERMISSIONS_FOR_CHECK.all {
        CC.checkSelfPermission(this, it) == PackageManager.PERMISSION_GRANTED
    }
}

private fun CameraInfo.matches(
    cameraId: String,
    physicalId: String?
): Boolean = this.id == cameraId && (this.physicalId == physicalId || (this.physicalId == null && physicalId == null))

@Composable
fun MainScreen(volumeKeyEventFlow: SharedFlow<Int>) {
    val context = LocalContext.current
    val cameraProvider = remember { CameraProvider(context) }
    val sensorCapture = remember { SensorCapture(context) }
