    var recordingDuration by remember { mutableIntStateOf(0) }
    var currentVideoFile by remember { mutableStateOf<File?>(null) }
    val captureVideo = remember { CaptureVideo() }

    var isRecordingLocked by remember { mutableStateOf(false) }
    var lockDragOffset by remember { mutableFloatStateOf(0f) }
    val lockThreshold = RECORDING_LOCK_THRESHOLD_DP.dp

    val glSurfaceView = remember { GLSurfaceView(context) }
    val perfOptimizer = remember { PerformanceOptimizer(context) }
    val locationTracker = remember { LocationTracker(context) }
    var activeThreads by remember { mutableStateOf(intArrayOf(Process.myTid())) }

    val livePreview = remember {
        LivePreview(context).apply {
            setOnFrameProcessedListener { timeMs ->
                val now = System.currentTimeMillis()
                if (now - lastProcessingUiUpdateTime > UI_UPDATE_THROTTLE_MS) {
                    processingTimeMs = timeMs
                    lastProcessingUiUpdateTime = now
                } else {
                    processingTimeMs = timeMs
                }
                perfOptimizer.reportActualWorkDuration(timeMs * 1_000_000L)
            }
            setOnVideoThreadIdAvailableListener { tid -> registerThread(tid, perfOptimizer) }
            setOnGlThreadIdAvailableListener { tid -> registerThread(tid, perfOptimizer) }
            setOnIspThreadIdAvailableListener { tid -> registerThread(tid, perfOptimizer) }
            setOnRawPreviewSurfaceReadyListener { surface ->
                rawPreviewSurface = surface
            }
            setRequestRenderCallback {
                glSurfaceView.requestRender()
            }
        }
    }

    fun registerThread(tid: Int, perfOptimizer: PerformanceOptimizer) {
        if (!activeThreads.contains(tid)) {
            Process.setThreadPriority(tid, Process.THREAD_PRIORITY_URGENT_DISPLAY)
            activeThreads = activeThreads + tid
            perfOptimizer.updateThreads(activeThreads)
        }
    }

    val captureExecutor = remember { Executors.newFixedThreadPool(2) }

    LaunchedEffect(captureExecutor) {
        val tids = mutableListOf<Int>()
        val latch = CountDownLatch(2)

        repeat(2) {
            captureExecutor.execute {
                val tid = Process.myTid()
                synchronized(tids) { tids.add(tid) }
                latch.countDown()
            }
        }

        withContext(CoroutinesDispatchers.IO) {
            latch.await()
        }

        if (tids.isNotEmpty()) {
            activeThreads = (activeThreads + tids).distinct().toIntArray()
            perfOptimizer.updateThreads(activeThreads)
            Log.d(LOG_TAG, "Capture threads added to ADPF: ${tids.joinToString()}")
        }
    }

    DisposableEffect(Unit) {
        onDispose {
            captureExecutor.shutdown()
        }
    }

    fun updatePipelineSettings() {
        livePreview.setPipelineSettings(
            useSpatialDenoise, useFalseColor, highlightRecoveryEnabled
        )
    }

    fun saveMediaToGallery(videoFile: File, location: android.location.Location?) {
        captureExecutor.execute {
            saveVideoToGallery(context, videoFile, location)
        }
    }

    val takePhoto = {
        val shutterStart = System.currentTimeMillis()
        locationTracker.updateLocation()

        val metadata = CaptureMetadata(
            iso = 0,
            exposureTimeNs = 0,
            focalLength = sensorCapture.getFocalLength(),
            aperture = sensorCapture.getAperture(),
            location = locationTracker.getLastLocation()
        )

        livePreview.requestCapture({ byteBuffer, width, height, timestamp, readbackTime, iso, shutter, meta, recycler ->
            captureExecutor.execute {
                val finalMeta = meta?.copy(iso = iso, exposureTimeNs = shutter)
                    ?: metadata.copy(iso = iso, exposureTimeNs = shutter)
                processCaptureInBackground(context, byteBuffer, width, height, timestamp, readbackTime, shutterStart, finalMeta)
                recycler()
            }
        }, metadata)
        glSurfaceView.requestRender()
    }

    fun startVideoRecording(videoFile: File) {
        val prefix = if (isComparisonEnabled) VIDEO_COMP_PREFIX else VIDEO_VID_PREFIX
        currentVideoFile = File(
            context.getExternalFilesDir(null),
            "${prefix}${System.currentTimeMillis()}.mp4"
        )
        currentVideoFile?.let { file ->
            if (isComparisonEnabled) {
                isComparisonMode = true
                livePreview.setComparisonMode(true)
            }

            livePreview.startVideoRecording(captureVideo, file, locationTracker.getLastLocation())
            isRecording = true
            sensorCapture.setAwbLock(true)
            recordingStartTime = System.currentTimeMillis()

            coroutineScope.launch {
                while (isRecording) {
                    recordingDuration = ((System.currentTimeMillis() - recordingStartTime) / 1000).toInt()
                    delay(1000)
                }
            }
        }
    }

    fun stopVideoRecording() {
        captureVideo.stopRecording()
        val droppedFrames = livePreview.stopVideoRecording()
        sensorCapture.setAwbLock(false)
        isRecording = false
        isRecordingLocked = false
        lockDragOffset = 0f

        if (isComparisonMode) {
            livePreview.setComparisonMode(isComparisonEnabled)
            isComparisonMode = false
        }

        if (droppedFrames > 0) {
            Toast.makeText(context, "Recording finished with $droppedFrames dropped frames", Toast.LENGTH_LONG).show()
        }

        currentVideoFile?.let { saveMediaToGallery(it, locationTracker.getLastLocation()) }
        currentVideoFile = null
    }

    val toggleVideo = {
        if (isRecording) {
            stopVideoRecording()
        } else {
            startVideoRecording(File(context.getExternalFilesDir(null), ""))
        }
    }

    LaunchedEffect(volumeKeyEventFlow) {
        volumeKeyEventFlow.collect { keyCode ->
            when (keyCode) {
                KeyEvent.KEYCODE_VOLUME_UP -> takePhoto()
                KeyEvent.KEYCODE_VOLUME_DOWN -> toggleVideo()
            }
        }
    }

    val lifecycleOwner = LocalLifecycleOwner.current
    var lifecycleEvent by remember { mutableStateOf(Lifecycle.Event.ON_ANY) }

    DisposableEffect(lifecycleOwner) {
        val observer = LifecycleEventObserver { _, event ->
            lifecycleEvent = event
        }
        lifecycleOwner.lifecycle.addObserver(observer)
        onDispose {
            lifecycleOwner.lifecycle.removeObserver(observer)
        }
    }

    val openedCameraKey = remember { mutableStateOf("") }

    LaunchedEffect(hasCameraPermission.value, selectedCameraId, selectedPhysicalId, lifecycleEvent, rawPreviewSurface) {
        if (!hasCameraPermission.value || selectedCameraId.isEmpty()) return@LaunchedEffect

        when (lifecycleEvent) {
            Lifecycle.Event.ON_PAUSE, Lifecycle.Event.ON_STOP -> handlePauseStop(
                context, sensorCapture, livePreview, glSurfaceView,
                isRecording, currentVideoFile, captureVideo,
                ::saveMediaToGallery, ::openedCameraKey, ::rawPreviewSurface
            )
            Lifecycle.Event.ON_RESUME, Lifecycle.Event.ON_START -> handleResumeStart(
                context, sensorCapture, livePreview, glSurfaceView,
                cameraProvider, hasCameraPermission, locationTracker,
                perfOptimizer, activeThreads, ::openedCameraKey,
                rawPreviewSurface, selectedCameraId, selectedPhysicalId, cameras,
                ::currentIsoRange, ::currentShutterRange,
                ::aeCompensationRange, ::aeCompensationStep,
                aeCompensation, manualIso, manualExposureTimeNs, lockExposure, useOis,
                ::currentFlickerHz, ::lastMetadataUiUpdateTime, ::currentIso,
                ::currentExposureTimeNs, ::rawPreviewSurface,
                useFalseColor, useSpatialDenoise, highlightRecoveryEnabled,
                autoLevelsMode, showHistogram, logRange
            )
        }
    }

    LaunchedEffect(hasCameraPermission.value) {
        if (hasCameraPermission.value) {
            cameras = cameraProvider.getAvailableCameras()
            if (cameras.isNotEmpty() && selectedCameraId.isEmpty()) {
                selectedCameraId = cameras.first().id
                selectedPhysicalId = cameras.find { it.zoomLabel == "1x" }?.physicalId
                    ?: cameras.first().physicalId
            }
        }
    }

    fun resetZoom() {
        zoomValue = ZOOM_DEFAULT
        livePreview.setMagnification(ZOOM_DEFAULT)
    }

    Scaffold(modifier = Modifier.fillMaxSize()) { innerPadding ->
        BoxWithConstraints(
            modifier = Modifier
                .fillMaxSize()
                .background(Color.Black)
        ) {
            val screenMaxWidth = maxWidth
            val screenMaxHeight = maxHeight

            val viewportHeight = screenMaxHeight * 0.9f
            val imageHeight = screenMaxWidth * (4f / 3f)
            val letterbox = (viewportHeight - imageHeight).coerceAtLeast(0.dp)
            val imageBottomFromTop = screenMaxHeight * GL_SURFACE_TOP_MARGIN + letterbox * 0.1f + imageHeight

            CameraContent(
                context = context,
                hasCameraPermission = hasCameraPermission.value,
                cameraProvider = cameraProvider,
                sensorCapture = sensorCapture,
                livePreview = livePreview,
                glSurfaceView = glSurfaceView,
                showDebugData = showDebugData,
                processingTimeMs = processingTimeMs,
                isShowingRawPreview = isShowingRawPreview,
                isRecording = isRecording,
                recordingDuration = recordingDuration,
                isRecordingLocked = isRecordingLocked,
                lockDragOffset = lockDragOffset,
                lockThreshold = lockThreshold,
                showSettings = showSettings,
                cameras = cameras,
                selectedCameraId = selectedCameraId,
                selectedPhysicalId = selectedPhysicalId,
                zoomValue = zoomValue,
                zoomRange = zoomRange,
                currentIso = currentIso,
                currentExposureTimeNs = currentExposureTimeNs,
                screenMaxWidth = screenMaxWidth,
                imageBottomFromTop = imageBottomFromTop,
                takePhoto = ::takePhoto,
                toggleVideo = ::toggleVideo,
                showSettings = showSettings,
                onShowSettingsChanged = { showSettings = it },
                onSelectedCameraChanged = { cam ->
                    selectedCameraId = cam.id
                    selectedPhysicalId = if (cam.isPhysical) cam.physicalId else null
                    resetZoom()
                },
                onZoomValueChange = { value ->
                    zoomValue = value
                    livePreview.setMagnification(value)
                },
                onShowRawPreviewChanged = { enabled ->
                    isShowingRawPreview = enabled
                    livePreview.setShowRawPreview(enabled)
                },
                onComparisonEnabledChanged = {
                    isComparisonEnabled = it
                    livePreview.setComparisonMode(it)
                },
                onIsoChanged = {
                    manualIso = it
                    sensorCapture.setManualIso(it)
                },
                onShutterChanged = {
                    manualExposureTimeNs = it
                    sensorCapture.setManualExposureTime(it)
                },
                onAutoLevelsModeChanged = { mode ->
                    autoLevelsMode = mode
                    livePreview.setAutoLevelsMode(mode)
                },
                onShowHistogramChanged = { show ->
                    showHistogram = show
                    livePreview.setShowHistogram(show)
                },
                onUseFalseColorChanged = { useFalseColor = it; updatePipelineSettings() },
                onUseSpatialDenoiseChanged = { useSpatialDenoise = it; updatePipelineSettings() },
                onColorSaturationChanged = {
                    colorSaturation = it
                    livePreview.setColorSaturation(it)
                },
                onOisChanged = {
                    useOis = it
                    sensorCapture.setUseOis(it)
                },
                onDebugDataChanged = { showDebugData = it },
                onHighlightRecoveryChanged = { highlightRecoveryEnabled = it; updatePipelineSettings() },
                onLogRangeChanged = {
                    logRange = it
                    livePreview.setLogRange(it)
                },
                onAeCompensationChanged = { aeCompensation = it; sensorCapture.setExposureCompensation(it) },
                onLockExposureChanged = {
                    lockExposure = it
                    sensorCapture.setAeLock(it)
                },
                aeCompensation = aeCompensation,
                aeCompensationRange = aeCompensationRange,
                aeCompensationStep = aeCompensationStep,
                lockExposure = lockExposure,
                liveIso = currentIso,
                isoRange = currentIsoRange,
                manualExposureTimeNs = manualExposureTimeNs,
                liveExposureTimeNs = currentExposureTimeNs,
                shutterRange = currentShutterRange,
                autoLevelsMode = autoLevelsMode,
                showHistogram = showHistogram,
                useFalseColor = useFalseColor,
                useSpatialDenoise = useSpatialDenoise,
                colorSaturation = colorSaturation,
                useOis = useOis,
                isComparisonEnabled = isComparisonEnabled,
                highlightRecoveryEnabled = highlightRecoveryEnabled,
                logRange = logRange,
                onDismissSettings = { showSettings = false }
            )
        }
    }
}

private fun handlePauseStop(
    context: Context,
    sensorCapture: SensorCapture,
    livePreview: LivePreview,
    glSurfaceView: GLSurfaceView,
    isRecording: Boolean,
    currentVideoFile: File?,
    captureVideo: CaptureVideo,
    saveMediaToGallery: (File, android.location.Location?) -> Unit
) {
    context.findActivity()?.let { activity ->
        try {
            context.unregisterReceiver(activity.getRecordingReceiver())
        } catch (_: Exception) {}
    }
    if (isRecording) {
        captureVideo.stopRecording()
        livePreview.stopVideoRecording()
        saveMediaToGallery(currentVideoFile!!, locationTrackerInstance(context).getLastLocation())
    }
    sensorCapture.closeCamera()
    livePreview.clearPendingImage()
    livePreview.cleanup()
    glSurfaceView.onPause()
}

private fun handleResumeStart(
    context: Context,
    sensorCapture: SensorCapture,
    livePreview: LivePreview,
    glSurfaceView: GLSurfaceView,
    cameraProvider: CameraProvider,
    hasCameraPermission: MutableState<Boolean>,
    locationTracker: LocationTracker,
    perfOptimizer: PerformanceOptimizer,
    activeThreads: IntArray,
    openedCameraKey: MutableState<String>,
    rawPreviewSurface: Surface?,
    selectedCameraId: String,
    selectedPhysicalId: String?,
    cameras: List<CameraInfo>,
    currentIsoRange: (Range<Int>) -> Unit,
    currentShutterRange: (Range<Long>) -> Unit,
    aeCompensationRange: (Range<Int>) -> Unit,
    aeCompensationStep: (Rational) -> Unit,
    aeCompensation: Int,
    manualIso: Int,
    manualExposureTimeNs: Long,
    lockExposure: Boolean,
    useOis: Boolean,
    currentFlickerHz: (Int) -> Unit,
    lastMetadataUiUpdateTime: (Long) -> Unit,
    currentIso: (Int) -> Unit,
    currentExposureTimeNs: (Long) -> Unit,
    rawPreviewSurfaceRef: (Surface?) -> Unit,
    useFalseColor: Int,
    useSpatialDenoise: Int,
    highlightRecoveryEnabled: Boolean,
    autoLevelsMode: Int,
    showHistogram: Boolean,
    logRange: Float
) {
    context.findActivity()?.let { activity ->
        val filter = android.content.IntentFilter(PACKAGE_ACTION_TOGGLE_VIDEO)
        CC.registerReceiver(context, activity.getRecordingReceiver(), filter, CC.RECEIVER_NOT_EXPORTED)
    }
    glSurfaceView.onResume()

    val effectiveCameraKey = "${selectedCameraId}:${selectedPhysicalId ?: ""}"
    if (rawPreviewSurface != null && openedCameraKey.value != effectiveCameraKey) {
        sensorCapture.closeCamera()
        livePreview.resetForCameraSwitch()

        sensorCapture.setOnSensorImageAvailableListener(object : SensorCapture.OnSensorImageAvailableListener {
            override fun onSensorImageAvailable(reader: ImageReader) {
                try {
                    reader.acquireNextImage()?.let { livePreview.updateSensorImage(it) }
                } catch (e: Exception) {
                    Log.e(LOG_TAG, "Error acquiring image", e)
                }
            }
        })

        sensorCapture.setOnMetadataAvailableListener(object : SensorCapture.OnMetadataAvailableListener {
            override fun onMetadataAvailable(
                iso: Int,
                exposureTimeNs: Long,
                dynamicBlackLevel: FloatArray?,
                awbGains: FloatArray?,
                colorMatrix: FloatArray?,
                intrinsics: FloatArray?,
                flickerHz: Int
            ) {
                livePreview.setIso(iso)
                livePreview.setExposureTime(exposureTimeNs)

                handleFlicker(flickerHz, manualExposureTimeNs, currentFlickerHz, sensorCapture)

                val now = System.currentTimeMillis()
                if (now - lastMetadataUiUpdateTime() > UI_UPDATE_THROTTLE_MS) {
                    currentIso(iso)
                    currentExposureTimeNs(exposureTimeNs)
                    lastMetadataUiUpdateTime(now)
                }

                livePreview.setBlackLevelPattern(dynamicBlackLevel ?: DEFAULT_BLACK_LEVEL)
                if (awbGains != null && !isRecordingGlobal()) {
                    livePreview.setWbGains(
                        maxOf(0.1f, awbGains[0]),
                        maxOf(0.1f, awbGains[1]),
                        maxOf(0.1f, awbGains[2])
                    )
                }
                colorMatrix?.let { livePreview.setColorMatrix(it) }
            }
        })

        setCameraParametersBeforeOpen(
            sensorCapture, livePreview, cameras, selectedCameraId, selectedPhysicalId,
            autoLevelsMode, showHistogram, logRange,
            useSpatialDenoise, useFalseColor, highlightRecoveryEnabled
        )

        sensorCapture.openCamera(selectedCameraId, selectedPhysicalId, rawPreviewSurface)
        openedCameraKey.value = effectiveCameraKey
        rawPreviewSurfaceRef(rawPreviewSurface)

        currentIsoRange(sensorCapture.getIsoRange())
        val rawShutterRange = sensorCapture.getShutterRange()
        currentShutterRange(Range(rawShutterRange.lower, minOf(rawShutterRange.upper, MAX_SHUTTER_NS)))
        aeCompensationRange(sensorCapture.getExposureCompensationRange())
        aeCompensationStep(sensorCapture.getExposureCompensationStep())
        sensorCapture.setManualIso(manualIso)
        sensorCapture.setManualExposureTime(manualExposureTimeNs)
        sensorCapture.setExposureCompensation(aeCompensation)
        sensorCapture.setAeLock(lockExposure)
        sensorCapture.setUseOis(useOis)

        perfOptimizer.enableSustainedPerformanceMode(context.findActivity()?.window ?: return@handleResumeStart)
        perfOptimizer.startPerformanceSession(activeThreads)
    }
}

private fun isRecordingGlobal(): Boolean = false

private fun handleFlicker(
    flickerHz: Int,
    manualExposureTimeNs: Long,
    currentFlickerHz: (Int) -> Int,
    sensorCapture: SensorCapture
) {
    if (flickerHz != currentFlickerHz(0) && flickerHz > 0 && manualExposureTimeNs > 0) {
        val period = if (flickerHz == 50) 10_000_000L else 8_333_333L
        val snapped = Math.max(1L, Math.round(manualExposureTimeNs.toDouble() / period) * period)
        if (snapped != manualExposureTimeNs) {
            currentFlickerHz(flickerHz)
            sensorCapture.setManualExposureTime(snapped)
        }
    }
}

private fun handleFlicker(
    flickerHz: Int,
    currentFlickerHz: Int,
    manualExposureTimeNs: Long,
    sensorCapture: SensorCapture,
    currentFlickerHzSetter: (Int) -> Unit
) {
    if (flickerHz != currentFlickerHz && flickerHz > 0 && manualExposureTimeNs > 0) {
        val period = if (flickerHz == 50) 10_000_000L else 8_333_333L
        val snapped = Math.max(1L, Math.round(manualExposureTimeNs.toDouble() / period) * period)
        if (snapped != manualExposureTimeNs) {
            currentFlickerHzSetter(flickerHz)
            sensorCapture.setManualExposureTime(snapped)
        }
    }
}

private fun setCameraParametersBeforeOpen(
    sensorCapture: SensorCapture,
    livePreview: LivePreview,
    cameras: List<CameraInfo>,
    selectedCameraId: String,
    selectedPhysicalId: String?,
    autoLevelsMode: Int,
    showHistogram: Boolean,
    logRange: Float,
    useSpatialDenoise: Int,
    useFalseColor: Int,
    highlightRecoveryEnabled: Boolean
) {
    val effectiveId = selectedPhysicalId ?: selectedCameraId
    val currentCameraInfo = cameras.find { it.matches(selectedCameraId, selectedPhysicalId) }

    livePreview.apply {
        setIsMirrored(currentCameraInfo?.facing == CameraCharacteristics.LENS_FACING_FRONT)
        setSensorOrientation(sensorCapture.getSensorOrientation(effectiveId))
        setCfaPattern(sensorCapture.getCfaPattern(effectiveId))
        setBlackLevelPattern(sensorCapture.getBlackLevelPattern(effectiveId))
        setWhiteLevel(sensorCapture.getWhiteLevel(effectiveId, selectedCameraId).toFloat())
        setDistortion(sensorCapture.getLensDistortion(effectiveId))
        setBlackLevelOffset(0.0f)
        setAutoLevelsMode(autoLevelsMode)
        setShowHistogram(showHistogram)
        setLogRange(logRange)
        setPipelineSettings(useSpatialDenoise, useFalseColor, highlightRecoveryEnabled)

        currentCameraInfo?.maxPreviewResolution?.let { size ->
            setRawPreviewResolution(size.width, size.height)
        }
    }
}

private fun CameraInfo.matches(cameraId: String, physicalId: String?): Boolean {
    return this.id == cameraId && (this.physicalId == physicalId || (this.physicalId == null && physicalId == null))
}

fun processCaptureInBackground(
    context: Context,
    byteBuffer: ByteBuffer,
    width: Int,
    height: Int,
    timestamp: Long,
    readbackTime: Long,
    shutterStartTime: Long,
    metadata: CaptureMetadata
) {
    try {
        val t0 = System.currentTimeMillis()
        val bitmap = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888)
        byteBuffer.rewind()
        bitmap.copyPixelsFromBuffer(byteBuffer)
        val t1 = System.currentTimeMillis()

        saveBitmapToGallery(context, bitmap, metadata, shutterStartTime, readbackTime, t1 - t0)
        bitmap.recycle()

        val t2 = System.currentTimeMillis()
        Log.d(LOG_TAG, "[PERF_CAPTURE] res=${width}x${height} total=${t2 - shutterStartTime}ms wait=${t0 - shutterStartTime}ms copy=${t1 - t0}ms write=${t2 - t1}ms readback=${readbackTime}ms")
    } catch (e: Exception) {
        Log.e(LOG_TAG, "Background capture failed: ${e.message}", e)
    }
}

fun saveBitmapToGallery(
    context: Context,
    bitmap: Bitmap,
    metadata: CaptureMetadata,
    shutterStart: Long,
    readbackTime: Long,
    bitmapTime: Long
) {
    val filename = "LATENT_${metadata.timestamp}.jpg"
    val mimeType = "image/jpeg"

    val contentValues = ContentValues().apply {
        put(MediaStore.MediaColumns.DISPLAY_NAME, filename)
        put(MediaStore.MediaColumns.MIME_TYPE, mimeType)
        put(MediaStore.MediaColumns.RELATIVE_PATH, "DCIM/Camera")
        val now = System.currentTimeMillis()
        put(MediaStore.MediaColumns.DATE_TAKEN, metadata.timestamp)
        put(MediaStore.MediaColumns.DATE_ADDED, now / 1000)
        put(MediaStore.MediaColumns.DATE_MODIFIED, now / 1000)
        put(MediaStore.MediaColumns.WIDTH, bitmap.width)
        put(MediaStore.MediaColumns.HEIGHT, bitmap.height)
        put(MediaStore.Images.ImageColumns.ORIENTATION, 0)
        put(MediaStore.MediaColumns.IS_PENDING, 1)
    }

    val uri = context.contentResolver.insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI, contentValues)
    uri?.let { imageUri ->
        try {
            val tStart = System.currentTimeMillis()
            context.contentResolver.openOutputStream(imageUri)?.use { outputStream ->
                bitmap.compress(Bitmap.CompressFormat.JPEG, 95, outputStream)
            }
            val tEncode = System.currentTimeMillis()

            context.contentResolver.openFileDescriptor(imageUri, "rw")?.use { pfd ->
                val exif = ExifInterface(pfd.fileDescriptor)
                exif.apply {
                    setAttribute(TAG_MAKE, metadata.make)
                    setAttribute(TAG_MODEL, metadata.model)
                    setAttribute(TAG_SOFTWARE, "Latent Camera")
                    setAttribute(TAG_ARTIST, "Latent Camera")
                    setAttribute(TAG_FOCAL_LENGTH, "${(metadata.focalLength * 1000).toInt()}/1000")
                    setAttribute(TAG_F_NUMBER, metadata.aperture.toString())
                    setAttribute(TAG_PHOTOGRAPHIC_SENSITIVITY, metadata.iso.toString())
                    val exposureTime = if (metadata.exposureTimeNs > 0) metadata.exposureTimeNs / 1_000_000_000.0 else 0.0
                    Log.d(LOG_TAG, "Writing EXIF: ISO=${metadata.iso}, Exp=${exposureTime}s, Focal=${metadata.focalLength}, Aperture=${metadata.aperture}, Location=${metadata.location}")
                    setAttribute(TAG_EXPOSURE_TIME, exposureTime.toString())
                }

                metadata.location?.let { loc ->
                    exif.setLatLong(loc.latitude, loc.longitude)
                    exif.setGpsInfo(loc)
                }
                exif.saveAttributes()
            }
            val tExif = System.currentTimeMillis()

            contentValues.clear()
            contentValues.put(MediaStore.MediaColumns.IS_PENDING, 0)
            context.contentResolver.update(imageUri, contentValues, null, null)

            if (BuildConfig.DEBUG) {
                Log.d(LOG_TAG, "[PERF_STILL] total=${tExif - shutterStart}ms readback=${readbackTime}ms bitmap=${bitmapTime}ms encode=${tEncode - tStart}ms exif=${tExif - tEncode}ms")
            }
        } catch (e: Exception) {
            Log.e(LOG_TAG, "Failed to save image or metadata", e)
            context.mainExecutor.execute {
                Toast.makeText(context, "Failed to save image", Toast.LENGTH_SHORT).show()
            }
        }
    }
}

@Composable
private fun CameraContent(
    context: Context,
    hasCameraPermission: Boolean,
    livePreview: LivePreview,
    sensorCapture: SensorCapture,
    glSurfaceView: GLSurfaceView,
    showDebugData: Boolean,
    processingTimeMs: Long,
    isShowingRawPreview: Boolean,
    isRecording: Boolean,
    recordingDuration: Int,
    isRecordingLocked: Boolean,
    lockDragOffset: Float,
    lockThreshold: androidx.compose.ui.unit.Dp,
    showSettings: Boolean,
    cameras: List<CameraInfo>,
    selectedCameraId: String,
    selectedPhysicalId: String?,
    zoomValue: Float,
    zoomRange: ClosedFloatingPointRange<Float>,
    currentIso: Int,
    currentExposureTimeNs: Long,
    screenMaxWidth: androidx.compose.ui.unit.Dp,
    imageBottomFromTop: androidx.compose.ui.unit.Dp,
    takePhoto: () -> Unit,
    toggleVideo: () -> Unit,
    onShowSettingsChanged: (Boolean) -> Unit,
    onSelectedCameraChanged: (CameraInfo) -> Unit,
    onZoomValueChange: (Float) -> Unit,
    onShowRawPreviewChanged: (Boolean) -> Unit,
    onComparisonEnabledChanged: (Boolean) -> Unit,
    onIsoChanged: (Int) -> Unit,
    onShutterChanged: (Long) -> Unit,
    onAutoLevelsModeChanged: (Int) -> Unit,
    onShowHistogramChanged: (Boolean) -> Unit,
    onUseFalseColorChanged: (Int) -> Unit,
    onUseSpatialDenoiseChanged: (Int) -> Unit,
    onColorSaturationChanged: (Float) -> Unit,
    onOisChanged: (Boolean) -> Unit,
    onDebugDataChanged: (Boolean) -> Unit,
    onHighlightRecoveryChanged: (Boolean) -> Unit,
    onLogRangeChanged: (Float) -> Unit,
    onAeCompensationChanged: (Int) -> Unit,
    onLockExposureChanged: (Boolean) -> Unit,
    aeCompensation: Int,
    aeCompensationRange: Range<Int>,
    aeCompensationStep: Rational,
    lockExposure: Boolean,
    liveIso: Int,
    isoRange: Range<Int>,
    manualExposureTimeNs: Long,
    liveExposureTimeNs: Long,
    shutterRange: Range<Long>,
    autoLevelsMode: Int,
    showHistogram: Boolean,
    useFalseColor: Int,
    useSpatialDenoise: Int,
    colorSaturation: Float,
    useOis: Boolean,
    isComparisonEnabled: Boolean,
    highlightRecoveryEnabled: Boolean,
    logRange: Float,
    onDismissSettings: () -> Unit
) {
    if (!hasCameraPermission) {
        Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
            Text("Camera permission required")
        }
        return
    }

    Column(modifier = Modifier.fillMaxSize()) {
        Spacer(modifier = Modifier.fillMaxHeight(GL_SURFACE_TOP_MARGIN))
        AndroidView(
            modifier = Modifier.fillMaxSize(),
            factory = { _ ->
                glSurfaceView.apply {
                    setEGLContextClientVersion(3)
                    setEGLConfigChooser { egl, display ->
                        val attribList = intArrayOf(
                            EGL14.EGL_RED_SIZE, 8,
                            EGL14.EGL_GREEN_SIZE, 8,
                            EGL14.EGL_BLUE_SIZE, 8,
                            EGL14.EGL_ALPHA_SIZE, 8,
                            EGL14.EGL_RENDERABLE_TYPE, EGL14.EGL_OPENGL_ES2_BIT,
                            EGLExt.EGL_RECORDABLE_ANDROID, 1,
                            EGL14.EGL_NONE
                        )
                        val configs = arrayOfNulls<javax.microedition.khronos.egl.EGLConfig>(1)
                        val numConfigs = IntArray(1)
                        egl.eglChooseConfig(display, attribList, configs, 1, numConfigs)
                        configs[0] ?: throw RuntimeException("No recordable EGL config found")
                    }
                    setRenderer(livePreview)
                    renderMode = GLSurfaceView.RENDERMODE_WHEN_DIRTY
                }
            }
        )
    }

    Column(
        modifier = Modifier
            .align(Alignment.TopCenter)
            .padding(top = 64.dp),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        val shutterSpeedText = formatShutterSpeed(currentExposureTimeNs)
        Text(
            text = "ISO $currentIso  |  $shutterSpeedText",
            modifier = Modifier.padding(top = 4.dp),
            color = Color.White,
            style = MaterialTheme.typography.bodyMedium
        )
        if (isShowingRawPreview) {
            Text(
                text = "Google Camera",
                modifier = Modifier.padding(top = 16.dp),
                color = Color.White.copy(alpha = 0.5f),
                style = MaterialTheme.typography.labelLarge
            )
        }
    }

    if (showDebugData) {
        val batteryPower = rememberBatteryPower()
        Column(
            modifier = Modifier
                .align(Alignment.TopEnd)
                .padding(top = 64.dp, end = 16.dp),
            horizontalAlignment = Alignment.End
