private fun handleFlicker(
    flickerHz: Int,
    manualExposureTimeNs: Long,
    currentFlickerHz: Int,
    sensorCapture: SensorCapture,
    currentFlickerHzSetter: (Int) -> Unit
) {
    if (flickerHz != currentFlickerHz && flickerHz > 0 && manualExposureTimeNs > 0) {
        val period = if (flickerHz == 50) 10_000_000L else 8_333_333L
        val snapped = Math.max(1L, Math.round(manualExposureTimeNs.toDouble() / period) * period)
        if (snapped != manualExposureTimeNs) {
            currentFlickerHzSetter(flickerHz)
            sensorCapture.setManualExposureTime(snapped)
        }
    }
}

@Composable
private fun ShutterLockRing(
    isRecording: Boolean,
    isRecordingLocked: Boolean,
    lockDragOffset: Float,
    lockThreshold: androidx.compose.ui.unit.Dp
) {
    if (isRecording && !isRecordingLocked) {
        val density = LocalDensity.current
        val thresholdPx = with(density) { lockThreshold.toPx() }
        val progress = (lockDragOffset / thresholdPx).coerceIn(0f, 1f)

        Box(
            modifier = Modifier
                .size(80.dp * (1f + progress * 0.6f))
                .background(
                    Color.Red.copy(alpha = 0.2f + progress * 0.4f),
                    CircleShape
                )
                .border(
                    width = 2.dp,
                    color = Color.White.copy(alpha = 0.3f + progress * 0.5f),
                    shape = CircleShape
                )
        )
    }
}

@Composable
private fun ShutterButton(
    isRecording: Boolean,
    isRecordingLocked: Boolean,
    onTakePhoto: () -> Unit,
    onToggleVideo: () -> Unit,
    onRecordingLockedChanged: (Boolean) -> Unit
) {
    var recordingLocked by remember { mutableStateOf(false) }
    var dragOffset by remember { mutableFloatStateOf(0f) }

    Box(
        modifier = Modifier
            .size(if (isRecording) 72.dp else 80.dp)
            .background(
                if (isRecording) Color.Red else Color.White,
                CircleShape
            )
            .pointerInput(Unit) {
                val thresholdPx = with(LocalDensity.current) { lockThreshold.toPx() }
                awaitPointerEventScope {
                    while (true) {
                        val down = awaitFirstDown()

                        if (isRecording) {
                            val up = waitForUpOrCancellation()
                            if (up != null) onToggleVideo()
                            continue
                        }

                        val longPressTimeout = viewConfiguration.longPressTimeoutMillis
                        val upChange = withTimeoutOrNull(longPressTimeout) {
                            while (true) {
                                val event = awaitPointerEvent()
                                val pointer = event.changes.firstOrNull() ?: break
                                if (pointer.pressed == false) return@withTimeoutOrNull pointer
                                pointer.consume()
                            }
                            null
                        }

                        if (upChange == null) {
                            onToggleVideo()
                            while (true) {
                                val event = awaitPointerEvent()
                                val pointer = event.changes.firstOrNull()

                                if (pointer == null || pointer.pressed == false) {
                                    if (!recordingLocked) onToggleVideo()
                                    dragOffset = 0f
                                    break
                                } else {
                                    val yOffset = down.position.y - pointer.position.y
                                    if (!recordingLocked) {
                                        dragOffset = yOffset.coerceAtLeast(0f)
                                        if (dragOffset >= thresholdPx) {
                                            recordingLocked = true
                                            dragOffset = 0f
                                        }
                                    }
                                    pointer.consume()
                                }
                            }
                        } else {
                            onTakePhoto()
                        }
                    }
                }
            }
    ) {
        if (recordingLocked) {
            Icon(
                Icons.Default.Lock,
                contentDescription = "Locked",
                tint = Color.White,
                modifier = Modifier.size(32.dp).align(Alignment.Center)
            )
        }
    }
}

