fun formatShutterSpeed(exposureTimeNs: Long): String {
    val exposureTimeUs = exposureTimeNs / 1000L
    if (exposureTimeUs <= 0L) return "OFF"
    val oneSecondUs = 1_000_000L
    if (exposureTimeUs >= oneSecondUs) {
        val seconds = exposureTimeUs / oneSecondUs.toDouble()
        return if (seconds == seconds.toLong()) {
            "${seconds.toLong()}s"
        } else {
            String.format("%.1fs", seconds)
        }
    }
    val denominator = oneSecondUs / exposureTimeUs
    if (denominator == 0L) return "OFF"
    if (exposureTimeUs * denominator >= oneSecondUs - exposureTimeUs) {
        return "1/${denominator}s"
    }
    val roundedDenominator = Math.round(oneSecondUs.toDouble() / exposureTimeUs.toDouble()).toLong()
    if (exposureTimeUs * roundedDenominator >= oneSecondUs - exposureTimeUs) {
        return "1/${roundedDenominator}s"
    }
    val exactSeconds = exposureTimeUs.toDouble() / oneSecondUs.toDouble()
    if (exactSeconds < 1.0) {
        return String.format("%.2fs", exactSeconds)
    }
    return "1/${roundedDenominator}s"
}

