_CASTLE_INFO = {
    "K": {"king": 60, "rook": 63, "dir": -1, "path": [61, 62]},
    "Q": {"king": 60, "rook": 56, "dir": 1,  "path": [59, 58, 57]},
    "k": {"king": 4,  "rook": 7,  "dir": -1, "path": [3, 2]},
    "q": {"king": 4,  "rook": 0,  "dir": 1,  "path": [3, 2, 1]},
}


def _apply_castling_rights(rights, moved_piece, moved_from, captured, captured_sq):
    """Return new castling rights after a piece move."""
    child_rights = set(rights)
    if moved_piece is None:
        return child_rights
    if moved_piece.kind == "k":
        if moved_piece.color == "w":
            child_rights.discard("K")
            child_rights.discard("Q")
        else:
            child_rights.discard("k")
            child_rights.discard("q")
    if moved_piece.kind == "r" and moved_from is not None:
        if moved_piece.color == "w":
            if moved_from == 63:
                child_rights.discard("K")
            elif moved_from == 56:
                child_rights.discard("Q")
        else:
            if moved_from == 7:
                child_rights.discard("k")
            elif moved_from == 0:
                child_rights.discard("q")
    if captured is not None and captured.kind == "r" and captured_sq is not None:
        if captured_sq == 63:
            child_rights.discard("K")
        elif captured_sq == 56:
            child_rights.discard("Q")
        elif captured_sq == 7:
            child_rights.discard("k")
        elif captured_sq == 0:
            child_rights.discard("q")
    return child_rights


def _castle_moves(active, rights, board):
    """Return list of (king_from, king_to) for legal castling."""
    moves = []
    for tag, info in _CASTLE_INFO.items():
        if tag not in rights:
            continue
        if tag[0].isupper() and active != "w":
            continue
        if tag[0].islower() and active != "b":
            continue
        king_sq = info["king"]
        if board[king_sq] is None or board[king_sq].kind != "k":
            continue
        if board[king_sq].color != active:
            continue
        rook_sq = info["rook"]
        if board[rook_sq] is None or board[rook_sq].kind != "r":
            continue
        if board[rook_sq].color != active:
            continue
        if any(board[s] is not None for s in info["path"]):
            continue
        enemy = "b" if active == "w" else "w"
        if _is_square_attacked(king_sq, enemy, board):
            continue
        if any(_is_square_attacked(sq, enemy, board) for sq in info["path"]):
            continue
        king_to = king_sq + info["dir"] * 2
        moves.append((king_sq, king_to))
    return moves


def legal_moves(fen: str) -> list[str]:
    board, active, rights = _parse_fen(fen)
    moves = []
    for idx in range(64):
        p = board[idx]
        if p is None or p.color != active:
            continue
        for dst in _attacks(idx, p.kind, p.color, board):
            moves.append(f"{_sq_name(idx)}{_sq_name(dst)}")
    for king_from, king_to in _castle_moves(active, rights, board):
        moves.append(f"{_sq_name(king_from)}{_sq_name(king_to)}")
    return moves


def _perft_on_board(board, depth_left, active, rights):
    if depth_left == 0:
        return 1
    total = 0

    # Regular moves (non-castling king moves are already covered by _attacks)
    for idx in range(64):
        p = board[idx]
        if p is None or p.color != active:
            continue
        for dst in _attacks(idx, p.kind, p.color, board):
            captured = board[dst]
            child = list(board)
            child[dst] = child[idx]
            child[idx] = None
            switch = "b" if active == "w" else "w"
            child_rights = _apply_castling_rights(rights, p, idx, captured, dst)
            total += _perft_on_board(child, depth_left - 1, switch, child_rights)

    # Castling moves (handled separately since they move both king and rook)
    for king_from, king_to in _castle_moves(active, rights, board):
        # Find which tag applies
        for tag, info in _CASTLE_INFO.items():
            if info["king"] != king_from:
                continue
            rook_src = info["rook"]
            rook_dst = king_from + info["dir"]
            child = list(board)
            child[rook_dst] = child[rook_src]
            child[rook_src] = None
            child[king_to] = child[king_from]
            child[king_from] = None
            switch = "b" if active == "w" else "w"
            child_rights = set(rights)
            child_rights.discard(tag)
            total += _perft_on_board(child, depth_left - 1, switch, child_rights)

    return total


def perft(fen: str, depth: int) -> int:
    board, active, rights = _parse_fen(fen)
    return _perft_on_board(board, depth, active, rights)

